for c in pdf_signing underskrift; do echo == $c; curl -s https://crates.io/api/v1/crates/$c -A x | python3 -c "import sys,json;d=json.load(sys.stdin)['crate'];print(d['max_version'],d['downloads'],d['updated_at'],d['repository'])"; v=$(curl -s https://crates.io/api/v1/crates/$c -A x | python3 -c "import sys,json;print(json.load(sys.stdin)['crate']['max_version'])"); curl -s https://crates.io/api/v1/crates/$c/$v/dependencies -A x | python3 -c "import sys,json;print([d['crate_id'] for d in json.load(sys.stdin)['dependencies'] if d['kind']=='normal'])"; done
